&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to work effectively within multidisciplinary teams spanning electrical, mechanical, software, cyber, systems and operational disciplines&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to produce clear technical documentation, communicate engineering recommendations and travel regularly within the UK and internationally&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Additional&amp;nbsp;Eligibility&amp;nbsp;Qualifications&lt;/strong&gt;&lt;/h3&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience designing expeditionary, deployable, ruggedised or rapidly reconfigurable RF capabilities&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience integrating RF systems onto airborne, vehicle-mounted, maritime, fixed-site or dismounted platforms&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Understanding of antenna selection, placement, radiation patterns, platform effects and co-site interference&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with wideband receivers, transmit chains, power amplifiers, low-noise amplifiers, filters and RF switching networks&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience conducting electromagnetic compatibility, electromagnetic environmental effects and radio-frequency interference assessments&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Familiarity with relevant defence, aviation, maritime, spectrum-management or RF engineering standards&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience supporting prototype builds, field trials, exercises, customer demonstrations or operational deployments&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;aaed607e-c2a3-5841-9fb4-41037bfa0faf|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[268442635,&amp;quot;24&amp;quot;,335559705,&amp;quot;1033&amp;quot;,335551547,&amp;quot;1033&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,469769226,&amp;quot;Times New Roman,Arial Unicode MS&amp;quot;,469775450,&amp;quot;paragraph&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;paragraph&amp;quot;,335572020,&amp;quot;1&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469789810,&amp;quot;none&amp;quot;,335572083,&amp;quot;0&amp;quot;,335572084,&amp;quot;0&amp;quot;,335572085,&amp;quot;4278190080&amp;quot;,469789802,&amp;quot;none&amp;quot;,335572075,&amp;quot;0&amp;quot;,335572076,&amp;quot;0&amp;quot;,335572077,&amp;quot;4278190080&amp;quot;,469789798,&amp;quot;none&amp;quot;,335572071,&amp;quot;0&amp;quot;,335572072,&amp;quot;0&amp;quot;,335572073,&amp;quot;4278190080&amp;quot;,469789806,&amp;quot;none&amp;quot;,335572079,&amp;quot;0&amp;quot;,335572080,&amp;quot;0&amp;quot;,335572081,&amp;quot;4278190080&amp;quot;,469789814,&amp;quot;none&amp;quot;,335572087,&amp;quot;0&amp;quot;,335572088,&amp;quot;0&amp;quot;,335572089,&amp;quot;4278190080&amp;quot;,469789818,&amp;quot;none&amp;quot;,335572091,&amp;quot;0&amp;quot;,335572092,&amp;quot;0&amp;quot;,335572093,&amp;quot;4278190080&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;Knowledge of systems engineering, size, weight, power and cooling analysis, low-volume manufacturing, &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;component&lt;/span&gt; &lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;obsolescence&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt; and through-life support&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
